# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#0f766e" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">İSLAM KÜLTÜR VE MEDENİYETİNİN ESASLARI I: İLMÎLİK VE ÖZGÜNLÜK</text>\n\n  <rect x="15" y="54" width="325" height="190" fill="#f0fdfa" stroke="#14b8a6" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="325" height="26" fill="#0d9488" rx="6"/>\n  <text x="177" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">1. İLMÎLİK ESASI (1.3)</text>\n  <text x="25" y="95" fill="#115e59" font-size="9.5" font-weight="bold">• Kur\'an-ı Kerim\'de İlim Kavramı:</text>\n  <text x="29" y="109" fill="#1e293b" font-size="9">İlim kesin hakikati ifade eder; Kur\'an\'da</text>\n  <text x="29" y="122" fill="#0f766e" font-size="9.5" font-weight="bold">yaklaşık 750 yerde</text>\n  <text x="122" y="122" fill="#1e293b" font-size="9">ilim ve eş anlamlıları geçer.</text>\n  <text x="29" y="137" fill="#0d9488" font-size="9" font-style="italic">"Allah Âdem\'e bütün isimleri öğretti." (Bakara, 31)</text>\n  <text x="25" y="155" fill="#115e59" font-size="9.5" font-weight="bold">• Bilginin Kaynakları ve İbadet Boyutu:</text>\n  <text x="29" y="169" fill="#1e293b" font-size="9">Kur\'an ve sahih sünnetin yanında <tspan font-weight="bold">selim akıl,</tspan></text>\n  <text x="29" y="182" fill="#1e293b" font-size="9"><tspan font-weight="bold">salim duyular ve tecrübe (deney/gözlem)</tspan> de</text>\n  <text x="29" y="195" fill="#1e293b" font-size="9">bilginin meşru kaynaklarıdır.</text>\n  <text x="29" y="212" fill="#115e59" font-size="9" font-weight="bold">• İlim tahsili nafile ibadetten üstün sayılmış,</text>\n  <text x="29" y="225" fill="#115e59" font-size="9" font-weight="bold">  dinî ve dünyevi ilim ayrımı yapılmamıştır.</text>\n\n  <rect x="360" y="54" width="325" height="190" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <rect x="360" y="54" width="325" height="26" fill="#2563eb" rx="6"/>\n  <text x="522" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">2. ÖZGÜNLÜK ESASI (1.4)</text>\n  <text x="370" y="95" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Tevhid Potasında Yeniden İnşa:</text>\n  <text x="374" y="109" fill="#1e293b" font-size="9">İran, Yunan ve Hint medeniyetlerinin birikimini</text>\n  <text x="374" y="122" fill="#1e293b" font-size="9">körü körüne taklitçi veya eklektik biçimde değil;</text>\n  <text x="374" y="135" fill="#1d4ed8" font-size="9" font-weight="bold">tevhid potasında eriterek (uygun olanı alıp,</text>\n  <text x="374" y="148" fill="#1d4ed8" font-size="9" font-weight="bold">aykırı olanı ıslah ederek/reddederek)</text>\n  <text x="374" y="161" fill="#1e293b" font-size="9">kendine has özgün bir kimlik kurmuştur.</text>\n  <text x="370" y="179" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Özgün Medeniyet İlkeleri:</text>\n  <text x="374" y="193" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Emir bi\'l-ma\'rûf nehiy ani\'l-münker</tspan> (İyiliği emir)</text>\n  <text x="374" y="208" fill="#1e293b" font-size="9">• <tspan font-weight="bold">"Halka hizmet Hakk\'a hizmettir"</tspan> düsturu</text>\n  <text x="374" y="223" fill="#1e293b" font-size="9">• <tspan font-weight="bold">"Yaratılanı Yaradan\'dan ötürü sevmek"</tspan> ahlakı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#7c2d12" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">İSLAM KÜLTÜR VE MEDENİYETİNİN ESASLARI II: YERELLİK VE EVRENSELLİK</text>\n\n  <rect x="15" y="54" width="325" height="190" fill="#fff7ed" stroke="#f97316" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="325" height="26" fill="#ea580c" rx="6"/>\n  <text x="177" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">3. YERELLİK ESASI (1.5)</text>\n  <text x="25" y="95" fill="#7c2d12" font-size="9.5" font-weight="bold">• Kültürel Farklılıklara Saygı:</text>\n  <text x="29" y="109" fill="#1e293b" font-size="9">Yayıldığı coğrafyalardaki (Türk, İran, Afrika,</text>\n  <text x="29" y="122" fill="#1e293b" font-size="9">Endülüs, Hint) yerel kültürleri zenginlik saymış,</text>\n  <text x="29" y="135" fill="#c2410c" font-size="9" font-weight="bold">kültürel asimilasyona kesinlikle karşı çıkmıştır.</text>\n  <text x="25" y="155" fill="#7c2d12" font-size="9.5" font-weight="bold">• Hukukta Örf ve Âdetin Yeri:</text>\n  <text x="29" y="169" fill="#1e293b" font-size="9">İslam hukukunda Kur\'an, sünnet, icma ve</text>\n  <text x="29" y="182" fill="#1e293b" font-size="9">kıyastan sonra (nassa aykırı olmamak şartıyla)</text>\n  <text x="29" y="195" fill="#1e293b" font-size="9"><tspan font-weight="bold">sahih örf ve âdetler</tspan> tali kaynak kabul edilmiştir.</text>\n  <text x="29" y="216" fill="#9a3412" font-size="9.2" font-weight="bold">• Mecelle Külli Kaidesi:</text>\n  <text x="29" y="231" fill="#c2410c" font-size="9.5" font-weight="bold">"Örf ile tayin, nass ile tayin gibidir."</text>\n\n  <rect x="360" y="54" width="325" height="190" fill="#fefce8" stroke="#eab308" stroke-width="1.5" rx="8"/>\n  <rect x="360" y="54" width="325" height="26" fill="#ca8a04" rx="6"/>\n  <text x="522" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">4. EVRENSELLİK ESASI (1.6)</text>\n  <text x="370" y="95" fill="#713f12" font-size="9.5" font-weight="bold">• Tüm İnsanlığa Hitap Eden Mesaj:</text>\n  <text x="374" y="109" fill="#1e293b" font-size="9">İslam belli bir ırka, sınıfa veya coğrafyaya</text>\n  <text x="374" y="122" fill="#1e293b" font-size="9">değil, kıyamete kadar tüm insanlığa gönderilmiştir.</text>\n  <text x="370" y="140" fill="#713f12" font-size="9.5" font-weight="bold">• Kur\'anî Dayanaklar:</text>\n  <text x="374" y="154" fill="#a16207" font-size="9" font-style="italic">• "Biz seni ancak âlemlere rahmet olarak</text>\n  <text x="374" y="167" fill="#a16207" font-size="9" font-style="italic">  gönderdik." (Enbiyâ, 107; ayrıca A\'râf, 158; Sebe, 28)</text>\n  <text x="370" y="185" fill="#713f12" font-size="9.5" font-weight="bold">• Evrensel İنسani Değerler:</text>\n  <text x="374" y="199" fill="#1e293b" font-size="9">• Irkçılık ve üstünlük iddialarının reddedilmesi</text>\n  <text x="374" y="213" fill="#1e293b" font-size="9">• Hak, hukuk, merhamet ve adaletin üstünlüğü</text>\n  <text x="374" y="227" fill="#1e293b" font-size="9">• Mazlumlara din ve milliyet ayrımı yapmadan yardım</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#1e3a8a" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">SULH (BARIŞ) ESASI (1.7) VE İSLAM YÖNETİM ANLAYIŞININ TEMELLERİ</text>\n\n  <rect x="15" y="54" width="330" height="190" fill="#ecfdf5" stroke="#10b981" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="330" height="26" fill="#059669" rx="6"/>\n  <text x="180" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">5. SULH (BARIŞ VE ESENLİK) ESASI (1.7)</text>\n  <text x="25" y="95" fill="#064e3b" font-size="9.5" font-weight="bold">• İslam ve Selâm / Silm Kökü:</text>\n  <text x="29" y="109" fill="#1e293b" font-size="9"><tspan font-weight="bold">İslam</tspan> kelimesi "barış, esenlik, güven ve huzur"</text>\n  <text x="29" y="122" fill="#1e293b" font-size="9">anlamındaki <tspan font-weight="bold" fill="#047857">selâm / silm</tspan> kökünden türemiştir.</text>\n  <text x="25" y="140" fill="#064e3b" font-size="9.5" font-weight="bold">• Kardeşlik ve Islah (Hucurât, 9-10):</text>\n  <text x="29" y="154" fill="#047857" font-size="9" font-style="italic">"Müminler ancak kardeştirler; öyleyse kardeşlerinizin</text>\n  <text x="29" y="167" fill="#047857" font-size="9" font-style="italic">arasını adaletle düzeltin (ıslah edin)."</text>\n  <text x="25" y="185" fill="#064e3b" font-size="9.5" font-weight="bold">• Medine Vesikası (25. Madde) ve Birlikte Yaşama:</text>\n  <text x="29" y="199" fill="#1e293b" font-size="9">Farklı inanç gruplarına din ve vicdan hürriyeti</text>\n  <text x="29" y="212" fill="#1e293b" font-size="9">tanınmış; zulüm ve sömürü yerine adil bir</text>\n  <text x="29" y="225" fill="#1e293b" font-size="9">barış düzeni (<tspan font-weight="bold">dârü\'s-selâm / sulh</tspan>) kurulmuştur.</text>\n\n  <rect x="355" y="54" width="330" height="190" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <rect x="355" y="54" width="330" height="26" fill="#2563eb" rx="6"/>\n  <text x="520" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">İSLAM YÖNETİM ANLAYIŞININ İLKELERİ</text>\n  <text x="365" y="95" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Yönetimin Gayesi:</text>\n  <text x="369" y="109" fill="#1e293b" font-size="9">Tahakküm ve zorbalık değil, yeryüzünde hakkı</text>\n  <text x="369" y="122" fill="#1e293b" font-size="9">ve adaleti tesis ederek erdemli toplum inşa etmektir.</text>\n  <text x="365" y="142" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Dört Temel Yönetim Esası:</text>\n  <text x="369" y="158" fill="#1e293b" font-size="9">1) <tspan font-weight="bold" fill="#1d4ed8">Hakikat ve Hukukun Üstünlüğü:</tspan> Gücün değil</text>\n  <text x="369" y="171" fill="#1e293b" font-size="9">   hakkın üstün tutulması.</text>\n  <text x="369" y="186" fill="#1e293b" font-size="9">2) <tspan font-weight="bold" fill="#1d4ed8">Adalet ve Emanet (Nisa, 58):</tspan> Görevlerin</text>\n  <text x="369" y="199" fill="#1e293b" font-size="9">   ehliyet ve liyakat sahiplerine verilmesi.</text>\n  <text x="369" y="214" fill="#1e293b" font-size="9">3) <tspan font-weight="bold" fill="#1d4ed8">İstişare (Şûrâ):</tspan> Ortak akılla karar alınması.</text>\n  <text x="369" y="229" fill="#1e293b" font-size="9">4) <tspan font-weight="bold" fill="#1d4ed8">Temel Hakların Korunması:</tspan> Can, mal, din, akıl, nesil.</text>\n</svg>']

def uygula(v):
    for i, s in enumerate(SVGS):
        if i < len(v.get('bolumler', [])):
            v['bolumler'][i]['gorsel'] = s
